<script setup>
import {computed,ref,onMounted,watch} from 'vue';
import Icon from './Icon.vue';
import BaseDialog from './BaseDialog.vue';
import {api,action,formatSize} from '../lib/api.js';
const props=defineProps({work:Object});
const snapshot=ref(null),selection=ref(new Set()),kind=ref('all'),query=ref(''),page=ref(0),loading=ref(false),busy=ref(false),error=ref(''),confirmOpen=ref(false),pending=ref([]),deleteError=ref('');
const pageSize=40;
const filtered=computed(()=>(snapshot.value?.files||[]).filter(file=>(kind.value==='all'||file.kind===kind.value||(kind.value==='orphan'&&file.orphan))&&`${file.path} ${file.session_title||''}`.toLowerCase().includes(query.value.trim().toLowerCase())));
const visible=computed(()=>filtered.value.slice(page.value*pageSize,(page.value+1)*pageSize));
const selected=computed(()=>(snapshot.value?.files||[]).filter(file=>selection.value.has(file.id)));
const bytes=computed(()=>selected.value.reduce((sum,file)=>sum+file.size,0));
const all=computed(()=>!!visible.value.length&&visible.value.every(file=>selection.value.has(file.id)));
const some=computed(()=>visible.value.some(file=>selection.value.has(file.id))&&!all.value);
const ratio=computed(()=>snapshot.value?.bytes?snapshot.value.totals.uploads.bytes/snapshot.value.bytes:0);
watch([kind,query],()=>page.value=0);
async function refresh(){if(busy.value||loading.value)return;loading.value=true;error.value='';try{snapshot.value=await api('/api/storage');selection.value.clear();page.value=0;}catch(reason){error.value=reason.message;}finally{loading.value=false;}}
onMounted(refresh);
function select(file,checked){if(checked&&selection.value.size>=500){props.work.notify('每次最多清理 500 个文件。');return;}checked?selection.value.add(file.id):selection.value.delete(file.id);}
function selectPage(checked){for(const file of visible.value){if(checked&&selection.value.size<500)selection.value.add(file.id);else if(!checked)selection.value.delete(file.id);}}
function orphans(){selection.value=new Set(snapshot.value.files.filter(file=>file.orphan).slice(0,500).map(file=>file.id));kind.value='orphan';query.value='';page.value=0;if(snapshot.value.orphan_files>500)props.work.notify('已选择前 500 个遗留文件，可分批清理。');}
function requestDelete(){if(!selected.value.length)return;pending.value=[...selected.value];deleteError.value='';confirmOpen.value=true;}
async function remove(){
  if(busy.value)return;busy.value=true;
  try{const result=await action('/api/storage/delete',{files:pending.value.map(file=>file.id)});confirmOpen.value=false;
    props.work.notify(`已清理 ${result.deleted} 个文件，释放 ${formatSize(result.released_bytes)}${result.failed.length?`；${result.failed.length} 个文件未能清理`:''}。`);
    await props.work.afterClean().catch(()=>props.work.notify('文件已清理，请刷新会话文件列表。'));busy.value=false;await refresh();
  }catch(reason){deleteError.value=reason.message;}finally{busy.value=false;}
}
</script>
<template><main id="page-storage" class="page library-page storage-page"><div class="storage-heading"><div><h1>存储管理</h1><p>查看本机文件占用，清理不再需要的附件与工作文件。</p></div><button class="secondary" :disabled="loading||busy" @click="refresh">{{loading?'正在统计…':'刷新统计'}}</button></div><p class="storage-error" role="status">{{error}}</p>
<template v-if="snapshot"><section class="storage-overview" aria-label="文件占用概览"><div class="storage-total-card"><svg id="storage-donut" viewBox="0 0 120 120" role="img" aria-label="上传附件与默认工作区占比" :class="{empty:snapshot.bytes===0}"><circle class="donut-track" cx="60" cy="60" r="45" pathLength="100"/><circle id="storage-donut-default" cx="60" cy="60" r="45" pathLength="100" :stroke-dasharray="`${(1-ratio)*100} ${ratio*100}`" :stroke-dashoffset="-ratio*100"/><circle id="storage-donut-uploads" cx="60" cy="60" r="45" pathLength="100" :stroke-dasharray="`${ratio*100} ${(1-ratio)*100}`"/></svg><div><span>可管理的文件占用</span><strong>{{formatSize(snapshot.bytes)}}</strong><small>{{snapshot.files.length.toLocaleString()}} 个文件{{snapshot.truncated?'（部分已扫描）':''}}</small></div></div><div class="storage-metric upload-metric"><span>上传附件</span><strong>{{formatSize(snapshot.totals.uploads.bytes)}}</strong><small>{{snapshot.totals.uploads.files}} 个文件</small></div><div class="storage-metric default-metric"><span>默认工作区</span><strong>{{formatSize(snapshot.totals.default.bytes)}}</strong><small>{{snapshot.totals.default.files}} 个文件</small></div><div class="storage-metric orphan-metric"><span>已删除会话的遗留文件</span><strong>{{formatSize(snapshot.orphan_bytes)}}</strong><small>{{snapshot.orphan_files}} 个文件可清理</small><button class="quiet" :disabled="!snapshot.orphan_files||busy||loading" @click="orphans">选择遗留文件</button></div></section>
<div class="storage-protected"><Icon name="shield"/><div><strong>{{snapshot.folders.length}} 个本地目录连接</strong><p>连接本地文件夹仅保存路径，不复制原文件；原目录不纳入此处的清理范围。</p><details><summary>查看连接目录与存储位置</summary><div v-for="folder in snapshot.folders" :key="folder.path+folder.title" class="storage-location"><span>{{folder.title}}</span><code>{{folder.path}}</code></div><p v-if="!snapshot.folders.length" class="storage-note">当前没有连接的本地文件夹。</p><div v-for="(path,location) in snapshot.locations" :key="location" class="storage-location"><span>{{location==='uploads'?'上传附件':'默认工作区'}}</span><code>{{path}}</code></div></details></div></div>
<p class="storage-note"><template v-if="snapshot.truncated">当前展示前 20,000 个文件，占用统计为已扫描部分；清理后可刷新继续管理。</template><template v-if="snapshot.skipped">有 {{snapshot.skipped}} 项因链接或权限原因未纳入清理。</template></p>
<section class="storage-list-panel" aria-label="可清理文件"><div class="storage-list-toolbar"><h2>文件明细</h2><div><label for="storage-filter" class="sr-only">筛选存储类型</label><select id="storage-filter" v-model="kind" :disabled="busy"><option value="all">全部位置</option><option value="uploads">上传附件</option><option value="default">默认工作区</option><option value="orphan">遗留文件</option></select><label for="storage-search" class="sr-only">搜索文件或会话</label><input id="storage-search" v-model="query" type="search" placeholder="搜索文件或会话" :disabled="busy"></div></div><div class="storage-table-scroll"><table class="storage-table"><thead><tr><th><input type="checkbox" aria-label="选择当前页文件" :checked="all" :indeterminate.prop="some" :disabled="busy||loading" @change="selectPage($event.target.checked)"></th><th>文件</th><th>存储位置 / 所属会话</th><th>大小</th></tr></thead><tbody><tr v-for="file in visible" :key="file.id"><td><input type="checkbox" :checked="selection.has(file.id)" :disabled="busy||loading" :aria-label="`选择文件：${file.path}`" @change="select(file,$event.target.checked)"></td><td class="storage-file-name"><div class="storage-file-heading"><Icon name="paperclip"/><strong>{{file.name}}</strong></div><small :title="file.path">{{file.kind==='uploads'?file.path.split('/').slice(1).join('/')||file.path:file.path}}</small></td><td class="storage-file-source"><span class="storage-kind">{{file.kind==='uploads'?'上传附件':'默认工作区'}}</span><small :class="{'orphan-label':file.orphan}">{{file.orphan?'已删除会话的遗留文件':file.session_title||'默认目录文件'}}</small></td><td class="storage-file-size">{{formatSize(file.size)}}</td></tr></tbody></table></div><p v-if="!filtered.length" class="storage-empty">没有符合条件的文件。</p><div class="storage-pagination"><span>{{filtered.length?`${page*pageSize+1}–${Math.min((page+1)*pageSize,filtered.length)} / ${filtered.length} 个文件`:'0 个文件'}}</span><div><button class="quiet" :disabled="page===0||busy" @click="page--">上一页</button><button class="quiet" :disabled="(page+1)*pageSize>=filtered.length||busy" @click="page++">下一页</button></div></div><div class="storage-selection"><span>已选 {{selected.length}} 个文件 · 可释放 {{formatSize(bytes)}}</span><div><button class="quiet" :disabled="busy" @click="selection.clear()">取消选择</button><button class="storage-danger" :disabled="!selected.length||busy||loading||work.busy.value" @click="requestDelete">清理所选</button></div></div></section>
<p class="storage-note">此处统计文件大小，不包含会话数据库。清理不会删除聊天记录；文件删除后无法恢复。</p></template>
<BaseDialog class="storage-confirm" :open="confirmOpen" :busy="busy" labelledby="storage-confirm-title" @close="confirmOpen=false"><h2 id="storage-confirm-title">确认永久清理</h2><p>将永久删除 {{pending.length}} 个文件，释放约 {{formatSize(pending.reduce((sum,file)=>sum+file.size,0))}}。</p><ul><li v-for="file in pending.slice(0,8)" :key="file.id">{{file.path}}</li><li v-if="pending.length>8">其余 {{pending.length-8}} 个所选文件</li></ul><p class="storage-note">所选文件将直接删除，无法恢复。聊天记录会保留，已删除的历史附件将显示为“已清理”。</p><p class="storage-error" role="status">{{deleteError}}</p><div class="storage-confirm-actions"><button class="secondary" :disabled="busy" @click="confirmOpen=false">取消</button><button class="storage-danger" :disabled="busy" @click="remove">{{busy?'正在清理…':`永久删除 ${pending.length} 个文件`}}</button></div></BaseDialog>
</main></template>
